import { h } from 'vue';
import Museum from '../components/view/ViewMuseum.vue';
import collection from '../data/archiveDemoCollection.json';

// The same pavilion, responsive panels and camera poses as the live Gallery.
// Only its clock and public collection are supplied by the demonstration.
const PreviewMuseum = {
  ...Museum,
  name: 'ArchivePreviewMuseum',
  inject: ['previewClock'],
  watch: {
    'previewClock.state'() { this.syncPreview(); },
    'previewClock.dark'() { this.syncTheme(); },
  },
  async mounted() {
    this._compactQuery = matchMedia('(max-width:767px) and (orientation:portrait),(max-width:1180px) and (max-height:600px) and (orientation:landscape)');
    this._portraitQuery = matchMedia('(max-width:767px) and (orientation:portrait)');
    this.syncCompact();
    this._compactQuery.addEventListener('change', this.syncCompact);
    this._portraitQuery.addEventListener('change', this.syncCompact);
    this._overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    this.$refs.dialog.showModal();
    this.tourActive = this.previewClock.scene !== 'access-gallery';
    this.selected = collection[0];
    this.dark = this.previewClock.dark;
    try {
      const [{ createMuseumScene }] = await Promise.all([
        import(/* webpackChunkName: "view-museum-scene" */ '../utils/viewMuseumScene'),
        document.fonts.ready, this.warmMuseumImages(collection),
      ]);
      if (this._closed) return;
      this._scene = createMuseumScene(this.$refs.space, {
        dark: this.dark, preview: true, arriving: true,
        playbackClock: () => this.previewClock.state.time,
        portraitElement: this.$refs.portraitAudio?.$el,
        onBoardControls: this.positionBoardControls,
        onReady: async () => {
          await Promise.all([this._scene.setExhibition(this.selected), this.syncWall()]);
          if (this._closed) return;
          this.ready = true;
          this.syncPreview();
          window.parent.postMessage({ type: 'archive-preview-gallery-ready' }, location.origin);
          window.parent.postMessage({ type: 'archive-preview-scene-ready', scene: this.previewClock.scene }, location.origin);
        },
        onError: () => { this.failure = true; },
      });
    } catch { this.failure = true; }
  },
  methods: {
    ...Museum.methods,
    rememberHall() {},
    prefetchView() {},
    syncCompact() {
      // Rotation updates the production layout without ending the preview's clock.
      this.compact = this._compactQuery.matches;
      this.portraitPhone = this._portraitQuery.matches;
      this.$nextTick(() => { this.measureContentPanels(); this.syncPreview(); });
    },
    syncPreview() {
      if (!this.ready || !this._scene) return;
      const { stopIndex, stop, previousStop, arrived, directoryExpanded } = this.previewClock.state;
      if (!stop) return;
      if (this.previewClock.state.time < (this._previewTime || 0)) this._previewStop = undefined;
      this._previewTime = this.previewClock.state.time;
      if (stopIndex !== this._previewStop) {
        // A standalone review may begin at any stop. Establish the preceding
        // pose before applying the same production journey to the destination.
        if (this._previewStop === undefined && stopIndex > 0) {
          const previous = previousStop;
          if (previous.area === 'hall') this._scene.setHallAngle(previous.angle, { instant: true });
          else this._scene.go(previous.area, { instant: true });
        }
        this._previewStop = stopIndex;
        this.area = stop.area;
        this.hallAngle = stop.angle || 'front';
        this.tourIndex = Math.max(0, stopIndex - 1);
        this.stationVisible = true;
        if(this.portraitPhone&&stop.area==='compose')this.$nextTick(this.measureComposer);
        const options = { durationMs: stop.travel, startedAt: stop.at };
        if (stop.area === 'hall') this._scene.setHallAngle(stop.angle, options);
        else this._scene.go(stop.area, options);
      }
      this.travelling = !arrived;
      this.tourMoving = !arrived;
      this.directoryExpanded = Boolean(directoryExpanded);
      this.panelOpen = (arrived || this.portraitPhone) && ['directory', 'compose', 'archive', 'about'].includes(stop.area);

      this._scene.renderFrame();
    },
  },
};

export default {
  name: 'ArchivePreviewGallery',
  emits: ['pageTitle'],
  render: () => h('div', [h(PreviewMuseum, { showcaseFrame: true, showcaseControls: true, views: collection, collection })]),
};
